import{_ as t,o as e,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-08-01","description":"","frontmatter":{"date":"2026-08-01T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-01-uxtrend.md","filePath":"daily/2026-08-01-uxtrend.md"}'),o={name:"daily/2026-08-01-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-08-01" tabindex="-1">设计趋势 - 2026-08-01 <a class="header-anchor" href="#设计趋势-2026-08-01" aria-label="Permalink to &quot;设计趋势 - 2026-08-01&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于人工智能时代的用户体验（Agentic UX）设计，强调与数字代理交互的新原则和人机信任建立。同时，指出AI工作流程设计常因模仿人类而非优化功能而失败。最值得关注的是，91%的设计师认为AI提升了设计质量，标志着用户体验设计正从以人为中心转向包含算法和代理的混合体验。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探索与数字设备交互的新类型用户体验设计原则。</p><p><strong>能解决什么问题</strong>: 如何设计能够满足人类需求的智能代理系统。</p><p><strong>产品应用</strong>: 可以应用到智能助手、自动化系统等产品中，以提升用户体验。</p><p><strong>示例场景</strong>: 智能助手协助用户进行日常任务规划和学习。</p><hr><h3 id="_2-人工智能时代的agentic-ux设计" tabindex="-1">2. 人工智能时代的Agentic UX设计 <a class="header-anchor" href="#_2-人工智能时代的agentic-ux设计" aria-label="Permalink to &quot;2. 人工智能时代的Agentic UX设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Agentic UX设计关注于建立人机之间的信任。</p><p><strong>能解决什么问题</strong>: 如何设计能让用户信任并与AI合作的智能系统。</p><p><strong>产品应用</strong>: 适用于需要AI辅助决策的企业系统，通过设计原则提升用户体验。</p><p><strong>示例场景</strong>: 在金融科技中，AI助手辅助用户进行投资决策。</p><hr><h3 id="_3-ai工作流程设计误区-模仿人类而非优化功能" tabindex="-1">3. AI工作流程设计误区：模仿人类而非优化功能 <a class="header-anchor" href="#_3-ai工作流程设计误区-模仿人类而非优化功能" aria-label="Permalink to &quot;3. AI工作流程设计误区：模仿人类而非优化功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://skooloflife.medium.com/the-biggest-mistake-in-ai-workflow-design-mimicking-human-process-instead-of-optimizing-function-628bfa37aa02" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI系统失败常因设计者将其视作“某人”而非“某物”。</p><p><strong>能解决什么问题</strong>: AI工作流程设计中错误地模仿人类行为，导致效率低下。</p><p><strong>产品应用</strong>: 适用于需要自动化和优化流程的产品，直接嵌入AI功能。</p><p><strong>示例场景</strong>: 自动化客服系统无需模拟人类对话，直接处理查询。</p><hr><h3 id="_4-人工智能时代下的用户体验2-0-代理体验设计" tabindex="-1">4. 人工智能时代下的用户体验2.0：代理体验设计 <a class="header-anchor" href="#_4-人工智能时代下的用户体验2-0-代理体验设计" aria-label="Permalink to &quot;4. 人工智能时代下的用户体验2.0：代理体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 用户体验设计正从以人为中心转向包括算法和代理在内的混合体验。</p><p><strong>能解决什么问题</strong>: 如何设计人与AI代理之间无缝、逻辑一致的交互体验。</p><p><strong>产品应用</strong>: 可应用于任何涉及AI代理的产品，如自动化客服、智能助手等。</p><p><strong>示例场景</strong>: AI代理帮助用户预约医生，同时理解用户意图。</p><hr><h3 id="_5-figma-2026年设计师现状-ai提升设计质量" tabindex="-1">5. Figma 2026年设计师现状：AI提升设计质量 <a class="header-anchor" href="#_5-figma-2026年设计师现状-ai提升设计质量" aria-label="Permalink to &quot;5. Figma 2026年设计师现状：AI提升设计质量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 91%的设计师认为AI提升了设计质量而非仅速度</p><p><strong>能解决什么问题</strong>: AI辅助设计提升效率和质量，但需人工完成细节</p><p><strong>产品应用</strong>: 适用于产品设计，AI辅助初稿，人工细化和决策</p><p><strong>示例场景</strong>: 设计师使用AI生成原型，再人工调整细节</p><hr><h3 id="_6-ai和llms在设计代理工作流中的新挑战与机遇" tabindex="-1">6. AI和LLMs在设计代理工作流中的新挑战与机遇 <a class="header-anchor" href="#_6-ai和llms在设计代理工作流中的新挑战与机遇" aria-label="Permalink to &quot;6. AI和LLMs在设计代理工作流中的新挑战与机遇&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/google-cloud/designing-cognitive-architectures-agentic-workflow-patterns-from-scratch-63baa74c54bc" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI和LLMs的发展带来了设计智能代理工作流的新挑战和机遇。</p><p><strong>能解决什么问题</strong>: 解决如何构建复杂、自适应的AI系统以应对多样化的实际问题。</p><p><strong>产品应用</strong>: 可应用于构建智能解决方案，如自纠正、知识扩展、任务协调和并行处理。</p><p><strong>示例场景</strong>: 使用自纠正模式自动优化AI代理的输出结果。</p><hr><h3 id="_7-为人工智能设计-设计人工智能特性的交互" tabindex="-1">7. 为人工智能设计：设计人工智能特性的交互 <a class="header-anchor" href="#_7-为人工智能设计-设计人工智能特性的交互" aria-label="Permalink to &quot;7. 为人工智能设计：设计人工智能特性的交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@ux.haowu/design-for-ai-2-designing-interactions-for-ai-features-d776d6388bdd" target="_blank" rel="noreferrer">Design for AI 2: Designing Interactions for AI Features</a></p><p><strong>一句话摘要</strong>: AI通过预测意图和实时补全，辅助用户而不影响工作流程。</p><p><strong>能解决什么问题</strong>: 解决用户在快节奏工作流中快速输入和减少错误的问题。</p><p><strong>产品应用</strong>: 可以应用到需要快速输入和减少输入错误的产品中，如邮件客户端和编程应用。</p><p><strong>示例场景</strong>: 在Figma中，地址字段自动补全用户可能的输入。</p><hr><h3 id="_8-ai代理工作流设计模式概览" tabindex="-1">8. AI代理工作流设计模式概览 <a class="header-anchor" href="#_8-ai代理工作流设计模式概览" aria-label="Permalink to &quot;8. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理和执行任务。</p><p><strong>产品应用</strong>: 可应用于开发智能代理，通过工作流模式灵活处理问题。</p><p><strong>示例场景</strong>: 智能客服系统使用ReAct模式处理客户咨询。</p><hr><h3 id="_9-引入ai-ux模式" tabindex="-1">9. 引入AI UX模式 <a class="header-anchor" href="#_9-引入ai-ux模式" aria-label="Permalink to &quot;9. 引入AI UX模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 收集并简化展示适用于成功AI体验的关键交互模式。</p><p><strong>能解决什么问题</strong>: 帮助设计师在涉及AI的产品规划中做出更好的UX决策。</p><p><strong>产品应用</strong>: 可作为功能参考，评估哪些模式最适合产品和用户。</p><p><strong>示例场景</strong>: 设计一个智能助手时，选择合适的交互模式。</p><hr><h3 id="_10-ai在设计工作流程优化中的实际应用" tabindex="-1">10. AI在设计工作流程优化中的实际应用 <a class="header-anchor" href="#_10-ai在设计工作流程优化中的实际应用" aria-label="Permalink to &quot;10. AI在设计工作流程优化中的实际应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@vicki-larson/ai-workflow-optimization-7-game-changing-tips-that-actually-work-414862126f5f" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI优化设计工作流程能显著提升效率。</p><p><strong>能解决什么问题</strong>: 设计工作流程效率低下，AI工具应用失败率高。</p><p><strong>产品应用</strong>: 可应用于设计领域，通过定制化AI工具提升效率。</p><p><strong>示例场景</strong>: 设计师使用Wegic工具快速原型设计。</p><hr>',75)])])}const m=t(o,[["render",s]]);export{c as __pageData,m as default};
